body:
:root {
  color-scheme: light;
  --gc-bg: #f6f7f9;
  --gc-surface: #ffffff;
  --gc-surface-alt: #eef1f5;
  --gc-border: #d8dee7;
  --gc-text: #1c2430;
  --gc-muted: #5c6b7f;
  --gc-accent: #2563eb;
  --gc-accent-text: #ffffff;
  --gc-ok-bg: #dcfce7;
  --gc-ok-text: #166534;
  --gc-down-bg: #fee2e2;
  --gc-down-text: #991b1b;
  --gc-warn-bg: #fef3c7;
  --gc-warn-text: #92400e;
  --gc-run-bg: #dbeafe;
  --gc-run-text: #1e40af;
  --gc-radius: 10px;
  --gc-shadow: 0 1px 2px rgba(16, 24, 40, 0.08), 0 1px 3px rgba(16, 24, 40, 0.06);
  --gc-mono: ui-monospace, SFMono-Regular, "Cascadia Mono", Consolas, monospace;
}

[data-theme="dark"] {
  color-scheme: dark;
  --gc-bg: #0f141b;
  --gc-surface: #171e28;
  --gc-surface-alt: #1e2733;
  --gc-border: #2d3a4a;
  --gc-text: #e6ebf2;
  --gc-muted: #9aa8ba;
  --gc-accent: #60a5fa;
  --gc-accent-text: #0b1220;
  --gc-ok-bg: #143526;
  --gc-ok-text: #86efac;
  --gc-down-bg: #3b1717;
  --gc-down-text: #fca5a5;
  --gc-warn-bg: #3a2c0c;
  --gc-warn-text: #fcd34d;
  --gc-run-bg: #14294a;
  --gc-run-text: #93c5fd;
  --gc-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --gc-bg: #0f141b;
    --gc-surface: #171e28;
    --gc-surface-alt: #1e2733;
    --gc-border: #2d3a4a;
    --gc-text: #e6ebf2;
    --gc-muted: #9aa8ba;
    --gc-accent: #60a5fa;
    --gc-accent-text: #0b1220;
    --gc-ok-bg: #143526;
    --gc-ok-text: #86efac;
    --gc-down-bg: #3b1717;
    --gc-down-text: #fca5a5;
    --gc-warn-bg: #3a2c0c;
    --gc-warn-text: #fcd34d;
    --gc-run-bg: #14294a;
    --gc-run-text: #93c5fd;
    --gc-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
  }
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--gc-bg);
  color: var(--gc-text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: var(--gc-accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

:focus-visible {
  outline: 2px solid var(--gc-accent);
  outline-offset: 2px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--gc-surface);
  padding: 0.5rem 0.75rem;
  z-index: 20;
}

.skip-link:focus {
  left: 0.5rem;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.site-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 1.25rem;
  background: var(--gc-surface);
  border-bottom: 1px solid var(--gc-border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.brand {
  font-weight: 700;
  font-size: 1.05rem;
  letter-spacing: 0.02em;
  color: var(--gc-text);
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  margin-right: auto;
}

.site-nav a {
  padding: 0.35rem 0.65rem;
  border-radius: 8px;
  color: var(--gc-muted);
  font-weight: 500;
}

.site-nav a:hover {
  background: var(--gc-surface-alt);
  color: var(--gc-text);
  text-decoration: none;
}

.content {
  width: 100%;
  max-width: 1080px;
  margin: 0 auto;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.panel {
  background: var(--gc-surface);
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  box-shadow: var(--gc-shadow);
  padding: 1rem 1.25rem 1.25rem;
}

.panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.75rem;
}

.panel-head h1,
.panel-head h2 {
  margin: 0;
  font-size: 1.15rem;
}

.health-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.75rem;
}

.card {
  background: var(--gc-surface-alt);
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  padding: 0.75rem 0.9rem;
}

.health-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.health-label {
  color: var(--gc-muted);
  font-weight: 500;
}

.badge,
.pill {
  display: inline-block;
  padding: 0.15rem 0.55rem;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: lowercase;
  letter-spacing: 0.01em;
}

.badge.ok {
  background: var(--gc-ok-bg);
  color: var(--gc-ok-text);
}

.badge.down {
  background: var(--gc-down-bg);
  color: var(--gc-down-text);
}

.pill.done {
  background: var(--gc-ok-bg);
  color: var(--gc-ok-text);
}

.pill.failed {
  background: var(--gc-down-bg);
  color: var(--gc-down-text);
}

.pill.partial {
  background: var(--gc-warn-bg);
  color: var(--gc-warn-text);
}

.pill.running {
  background: var(--gc-run-bg);
  color: var(--gc-run-text);
}

.pill.queued {
  background: var(--gc-surface-alt);
  color: var(--gc-muted);
  border: 1px solid var(--gc-border);
}

.quick-find {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

input,
select,
textarea {
  background: var(--gc-surface);
  color: var(--gc-text);
  border: 1px solid var(--gc-border);
  border-radius: 8px;
  padding: 0.5rem 0.65rem;
  font: inherit;
}

.quick-find input {
  flex: 1 1 260px;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  padding: 0.5rem 0.9rem;
  border-radius: 8px;
  border: 1px solid var(--gc-border);
  background: var(--gc-surface);
  color: var(--gc-text);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.button:hover {
  background: var(--gc-surface-alt);
}

.button.primary {
  background: var(--gc-accent);
  border-color: var(--gc-accent);
  color: var(--gc-accent-text);
}

.button.primary:hover {
  background: color-mix(in srgb, var(--gc-accent) 92%, white);
}

.button.ghost {
  background: transparent;
}

.table-wrap {
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th,
.data-table td {
  text-align: left;
  padding: 0.55rem 0.6rem;
  border-bottom: 1px solid var(--gc-border);
  white-space: nowrap;
}

.data-table thead th {
  color: var(--gc-muted);
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.data-table tbody tr:hover {
  background: var(--gc-surface-alt);
}

.mono {
  font-family: var(--gc-mono);
  font-size: 0.85em;
}

.empty-state {
  text-align: center;
  padding: 1.5rem 1rem;
  border: 1px dashed var(--gc-border);
  border-radius: var(--gc-radius);
  color: var(--gc-text);
}

.empty-state p {
  margin: 0.2rem 0;
}

.error-state {
  border-color: var(--gc-down-text);
  border-style: solid;
  background: var(--gc-down-bg);
  color: var(--gc-down-text);
}

.muted {
  color: var(--gc-muted);
}

.progress {
  width: 100%;
  height: 8px;
  border-radius: 999px;
  background: var(--gc-surface-alt);
  border: 1px solid var(--gc-border);
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  background: var(--gc-accent);
  width: 100%;
  transform-origin: left center;
  transform: scaleX(var(--progress, 0));
  transition: transform 0.2s ease;
}

.diff-section .data-table tbody tr,
#run-table tbody tr {
  content-visibility: auto;
  contain-intrinsic-size: 1.9rem;
}

.toast {
  position: fixed;
  right: 1rem;
  bottom: 1rem;
  max-width: 360px;
  padding: 0.65rem 0.9rem;
  border-radius: var(--gc-radius);
  background: var(--gc-down-bg);
  color: var(--gc-down-text);
  border: 1px solid var(--gc-border);
  box-shadow: var(--gc-shadow);
  z-index: 30;
}

.toast .button {
  margin-left: 0.35rem;
}

.filter-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.recent-filters {
  margin: 0 0 0.75rem;
}

.recent-filters ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0.35rem 0 0;
  padding: 0;
}

.filter-section {
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  padding: 0.75rem 0.9rem 0.9rem;
}

.filter-section h2 {
  margin: 0 0 0.6rem;
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--gc-muted);
}

.field-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 0.65rem;
}

.field,
.count-row {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin: 0;
  padding: 0;
  border: 0;
}

.field-label {
  color: var(--gc-muted);
  font-size: 0.8rem;
  font-weight: 600;
}

.field-input {
  width: 100%;
}

.field-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin: 0.6rem 0 0;
  padding: 0.5rem 0.65rem;
  border: 1px dashed var(--gc-border);
  border-radius: 8px;
}

.field-group[disabled] {
  opacity: 0.55;
}

.checkbox {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.count-row {
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  border: 1px solid var(--gc-border);
  border-radius: 8px;
  padding: 0.4rem 0.55rem;
}

.count-row .field-label {
  flex: 1 1 100%;
}

.count-row .field-input {
  flex: 1 1 70px;
  width: auto;
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.form-actions form {
  margin: 0;
}

.run-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  color: var(--gc-muted);
}

.run-hash-wrap {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.run-status-line {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 0.75rem;
}

.run-counts {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 0.4rem;
  color: var(--gc-muted);
}

.run-counts .count strong {
  color: var(--gc-text);
}

.flags {
  margin-top: 0.75rem;
}

.flags ul,
.warnings {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.flag,
.warnings li {
  padding: 0.4rem 0.6rem;
  border-radius: 8px;
  background: var(--gc-warn-bg);
  color: var(--gc-warn-text);
}

.flag.error {
  background: var(--gc-down-bg);
  color: var(--gc-down-text);
}

.sort-link {
  color: inherit;
  font: inherit;
  text-transform: inherit;
  letter-spacing: inherit;
}

.sort-link.active {
  color: var(--gc-accent);
}

.confidence {
  color: var(--gc-muted);
  font-size: 0.8em;
}

.flags-cell .flag {
  margin-right: 0.25rem;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 0.75rem;
}

.modal[hidden] {
  display: none;
}

.modal {
  position: fixed;
  inset: 0;
  background: rgba(15, 20, 27, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  z-index: 40;
}

.modal-panel {
  background: var(--gc-surface);
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  box-shadow: var(--gc-shadow);
  padding: 1rem 1.25rem 1.25rem;
  width: min(520px, 100%);
}

.clone-limit-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.clone-limit-row label {
  flex: 1 1 100%;
  color: var(--gc-muted);
  font-weight: 600;
}

.clone-limit-row input[type="range"] {
  flex: 1 1 220px;
  padding: 0;
}

.clone-limit-row input[type="number"] {
  width: 5.5rem;
}

.clone-modes {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  border: 1px dashed var(--gc-border);
  border-radius: 8px;
  padding: 0.5rem 0.65rem;
  margin: 0 0 0.75rem;
}

.clone-modes legend {
  color: var(--gc-muted);
  font-size: 0.8rem;
  font-weight: 600;
  padding: 0 0.25rem;
}

.clone-estimate {
  margin-bottom: 0.75rem;
}

.clone-estimate p {
  margin: 0.2rem 0;
}

.row-selected {
  background: var(--gc-run-bg);
  outline: 2px solid var(--gc-accent);
  outline-offset: -2px;
}

.run-filters,
.diff-baseline-form {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.65rem;
  margin-bottom: 0.9rem;
}

.run-filters .field,
.diff-baseline-form .field {
  flex: 1 1 220px;
}

.inline-form {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0;
}

.inline-input {
  width: 9rem;
}

.library-actions,
.history-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
}

.button.danger {
  border-color: var(--gc-down-text);
  color: var(--gc-down-text);
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.diff-card {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.diff-card strong {
  font-size: 1.5rem;
}

.diff-label {
  color: var(--gc-muted);
  font-weight: 600;
  text-transform: uppercase;
  font-size: 0.78rem;
  letter-spacing: 0.04em;
}

.diff-section {
  margin-bottom: 1rem;
}

.diff-direction {
  margin: 0.5rem 0 0;
}

kbd {
  background: var(--gc-surface-alt);
  border: 1px solid var(--gc-border);
  border-radius: 5px;
  padding: 0.05rem 0.35rem;
  font-family: var(--gc-mono);
  font-size: 0.85em;
}

.htmx-indicator {
  display: none;
}

.htmx-request .htmx-indicator,
.htmx-request.htmx-indicator {
  display: inline;
}

.nav-progress {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  z-index: 50;
  background: var(--gc-accent);
  opacity: 0.75;
}

html[data-busy="true"] .nav-progress {
  display: block;
  animation: gc-busy-pulse 1s ease-in-out infinite;
}

@keyframes gc-busy-pulse {
  50% {
    opacity: 0.25;
  }
}

a.htmx-request,
.button.htmx-request {
  cursor: progress;
  opacity: 0.7;
}

.shortcuts-table td {
  white-space: normal;
}

@media (max-width: 640px) {
  .site-header {
    flex-wrap: wrap;
  }

  .content {
    padding: 0.9rem;
  }
}
